const icon = (name,cls='') => `<svg${cls?` class="${cls}"`:''} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name] || ICONS.shield}</svg>`;
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.outerHTML=icon(el.dataset.icon,el.className?.baseVal??el.className??'');});root.querySelectorAll('[data-game-icon]').forEach(el=>{el.outerHTML=gameIcon(el.dataset.gameIcon,el.className||'');});}
const $ = (q,root=document) => root.querySelector(q);
const $$ = (q,root=document) => [...root.querySelectorAll(q)];
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number = v => Number(v||0).toLocaleString('en-US');
const compact = v => v>=1000000 ? `${(v/1000000).toFixed(2).replace(/0$/,'').replace(/\.$/,'')}M` : v>=1000 ? `${(v/1000).toFixed(v>=100000?0:1).replace(/\.0$/,'')}K` : number(v);
const uid = () => crypto.randomUUID();
const localDay = value => {const d=new Date(value);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const STORE='raidroom.records.v1';
const VIEWS={overview:'Overview',battles:'Battle log',village:'My village',leaderboard:'Loot leaderboard',replays:'Replay library',giveaways:'Giveaways',capital:'Capital raids',games:'Clan Games'};
const TYPES=['Multiplayer','Clan war','CWL','Defense'];
const SHIPPED_UNITS=new Set(['heroes/barbarian_king','heroes/archer_queen','heroes/grand_warden','heroes/royal_champion','heroes/minion_prince','heroes/dragon_duke','troops/dragon','troops/electro_dragon','troops/balloon','troops/healer','troops/hog_rider','troops/valkyrie','troops/wizard','troops/golem','spells/rage_spell','spells/freeze_spell','spells/healing_spell','spells/invisibility_spell']);
function gameSlug(name){return String(name).toLowerCase().replace(/[.?‘’']/g,'').replaceAll(' ','_').replace(/[^a-z0-9_]/g,'');}
function townHallArt(level,cls=''){const n=Math.max(1,Math.trunc(Number(level)||1));const path=`buildings/home-village/town_hall/level_${n}.webp`;return `<span class="game-art townhall-art ${cls}" role="img" aria-label="Town Hall ${n}"><img src="${n<=18?'./assets/game/':'https://assets.clashk.ing/'}${path}" alt="" loading="lazy" data-game-art><b aria-hidden="true">${n}</b>${icon('castle')}</span>`;}
function unitArt(name,kind){const slug=gameSlug(name),key=`${kind}/${slug}`,path=kind==='spells'?`${key}.webp`:`${key}/icon.webp`;return `<span class="game-art unit-art"><img src="${SHIPPED_UNITS.has(key)?'./assets/game/':'https://assets.clashk.ing/'}${path}" alt="${esc(name)}" loading="lazy" data-game-art>${icon(kind==='heroes'?'crown':kind==='spells'?'wand':'shield')}</span>`;}
function resourceArt(name){return `<img class="resource-art" src="./assets/game/resources/${name}.webp" alt="" loading="lazy" aria-hidden="true">`;}
const GAME_INTERFACE_ART={grid:'interface/clan_castle.png',users:'heroes/barbarian_king/icon.webp',trophy:'interface/trophy.png',swords:'interface/wood_swords.png',shield:'interface/shield.png',coins:'resources/gold.webp',castle:'buildings/home-village/town_hall/level_17.webp',gift:'interface/gold_pass.png'};
function gameIcon(name,cls=''){const path=GAME_INTERFACE_ART[name];return path?`<img class="game-ui-icon ${esc(cls)}" src="./assets/game/${path}" alt="" aria-hidden="true" width="24" height="24" decoding="async">`:icon(name,cls);}
let view=VIEWS[location.hash.slice(1)]?location.hash.slice(1):'overview';
let battleFilter='all',battleQuery='',battlePeriod='all',battlePage=0,chartPeriod=7,leaderPeriod='today';
let apiConnected=false,objectUrls=[],modalCleanup=null;

function loadState(){try{const raw=localStorage.getItem(STORE);if(raw){const migrated=RaidroomRecords.migrateState(JSON.parse(raw));try{localStorage.setItem(STORE,JSON.stringify(migrated));}catch{}return migrated;}}catch{}return RaidroomRecords.emptyState();}
let state=loadState();
function hasPlayer(){return !!state.player.tag;}
function saveState(){try{localStorage.setItem(STORE,JSON.stringify(state));return true;}catch{toast('Storage is full or unavailable. Export your records to keep a backup.');return false;}}
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=icon('check')+`<span>${esc(message)}</span>`;$('#toast-region').append(el);setTimeout(()=>el.remove(),5200);}
function sourceBadge(){return '<span class="source-badge">'+(state.source==='api'?'Imported API profile':state.source==='import'?'Imported profile':'Personal records')+'</span>';}
function sourceNote(){return '<div class="source-note">'+sourceBadge()+'<span>Saved on this device</span></div>';}
function pageHeading(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div><div class="heading-actions">${action}</div></div>`;}
function renderDisconnected(){
  const headings={overview:['Your village, in focus.','Connect your player tag to start tracking your progress.'],battles:['Your battle journal.','Connect a player to load recent attacks and defenses.'],village:['Your village starts here.','Your name, level, Town Hall, troops, and heroes will appear after lookup.'],ranked:['Your ranked story.','Connect a player to see their league, rankings, and reported battles.'],leaderboard:['Your biggest hauls.','Loot rankings are built from your connected village’s recorded attacks.']};
  const [title,description]=headings[view]||headings.overview;
  return pageHeading('YOUR COMMAND CENTER',title,description)+`<section class="panel connect-empty"><div class="connect-empty-art"><img src="./assets/clash-official-banner.jpg" alt="Official Clash of Clans artwork featuring an Electro Dragon and attacking troops" fetchpriority="high"><span>ART © SUPERCELL</span></div><div class="connect-empty-content"><span class="live-badge">${icon('shield')}Public player data</span><h2>Connect your village.</h2><p>Enter your Clash of Clans player tag. We’ll find your village and load the details straight from the game.</p><button class="button button-lime" data-action="player">${icon('search')}Find my village ${icon('arrow-right')}</button><small>Your player tag is beneath your name in your in-game profile.</small></div></section><div class="empty-feature-grid">${[['castle','Your real village','Name, Town Hall, player level, and unit levels.'],['swords','Your recent battles','Attack and defense results where providers report them.'],['trophy','Your place on the climb','League, available rankings, and your best recorded loot.']].map(([ico,label,copy])=>`<section class="panel empty-feature"><span class="stat-icon">${icon(ico)}</span><div><h3>${label}</h3><p>${copy}</p></div></section>`).join('')}</div>`;
}
function todayBattles(){const today=localDay(new Date());return state.battles.filter(b=>localDay(b.date)===today&&b.type!=='Defense');}
function totalLoot(battles){return battles.reduce((n,b)=>n+b.gold+b.elixir,0);}
function stars(n){return `<span class="stars" aria-label="${n} out of 3 stars">${[0,1,2].map(i=>icon('star',i>=n?'empty-star':'')).join('')}</span>`;}
function relativeDate(date){const mins=Math.floor((Date.now()-new Date(date).getTime())/60000);if(mins<0)return new Date(date).toLocaleDateString('en-US',{month:'short',day:'numeric'});if(mins<1)return 'Just now';if(mins<60)return `${mins}m ago`;if(mins<1440)return `${Math.floor(mins/60)}h ago`;if(mins<2880)return 'Yesterday';return new Date(date).toLocaleDateString('en-US',{month:'short',day:'numeric'});}
function statCard(label,value,ico,color,detail,spark){return `<div class="stat-card"><div class="stat-label"><span>${label}</span><span class="stat-icon ${color}">${icon(ico)}</span></div><div class="stat-number">${value}</div><div class="stat-bottom">${detail}</div>${spark?`<svg class="sparkline" viewBox="0 0 90 32" fill="none" aria-hidden="true"><path d="M0 30 ${spark} L90 32H0Z" fill="#5588e7" opacity=".08"/><path d="M0 30 ${spark}" stroke="#5588e7" stroke-width="1.8" stroke-linejoin="round"/></svg>`:''}</div>`;}
function playerPanel(){const p=state.player;return `<section class="panel player-panel"><div class="profile-overline"><span>Your village</span>${icon('shield')}</div><div class="player-summary"><div class="profile-townhall">${townHallArt(p.townHallLevel)}<span class="player-xp">LVL ${number(p.expLevel)}</span></div><div><h3>${esc(p.name)}</h3><p>${esc(p.tag)} <button class="text-link" data-action="copy-tag" aria-label="Copy player tag">${icon('copy')}</button></p></div></div><div class="profile-meta"><div><small>Town Hall</small><strong>Level ${number(p.townHallLevel)}</strong></div><div><small>League</small><strong>${esc(p.league?.name||'Unranked')}</strong></div><div><small>Clan</small><strong>${esc(p.clan?.name||'No clan')}</strong></div><div><small>Best trophies</small><strong>${icon('trophy')}${number(p.bestTrophies||p.trophies)}</strong></div></div><div class="xp-track"><div class="xp-label"><span>Recorded ${'attacks'}</span><strong>${state.battles.filter(b=>b.type!=='Defense').length} total</strong></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,state.battles.filter(b=>b.type!=='Defense').length/20*100)}%"></div></div></div><a class="profile-link" href="#village">Explore my village ${icon('arrow-up-right')}</a></section>`;}
function leaderboardData(period=leaderPeriod){const now=Date.now();return state.battles.filter(b=>b.type!=='Defense'&&(period==='all'||period==='week'&&now-new Date(b.date).getTime()<7*86400000||period==='today'&&localDay(b.date)===localDay(now))).sort((a,b)=>(b.gold+b.elixir)-(a.gold+a.elixir));}
function lootPanel(){const best=leaderboardData('today').slice(0,3);return `<section class="panel loot-panel"><div class="panel-header"><div class="section-topline" style="margin-bottom:0"><div class="section-heading">${icon('flame')}<h2>Today’s top loot</h2></div><span class="source-badge">${'Your raids'}</span></div><p class="loot-subtitle">Big raids. Even bigger rewards.</p></div><div class="leader-list">${best.length?best.map((b,i)=>`<button class="leader-item" data-battle="${esc(b.id)}" style="width:100%;text-align:left"><span class="rank ${i===0?'first':''}">0${i+1}</span><span class="leader-avatar ${i===0?'gold':i===2?'purple':''}">${esc(b.opponent.slice(0,1))}</span><span class="leader-info"><strong>${esc(b.opponent)}</strong><small>${Number.isFinite(b.stars)?b.stars+' stars':'Stars unavailable'}${Number.isFinite(b.townHall)?' · TH '+b.townHall:''}</small></span><span class="leader-value">${compact(b.gold+b.elixir)}</span></button>`).join(''):'<p class="no-results">Your next raid could take the top spot.</p>'}</div><a href="#leaderboard" class="panel-foot"><span>See the loot leaderboard</span>${icon('arrow-up-right')}</a></section>`;}
function battleTabs(){return `<div class="table-tabs" role="tablist" aria-label="Battle types">${[['all','All battles'],['Multiplayer','Multiplayer'],['war','Clan wars']].map(([value,label])=>`<button role="tab" aria-selected="${battleFilter===value}" class="table-tab ${battleFilter===value?'active':''}" data-filter="${value}">${label}</button>`).join('')}</div>`;}
function filteredBattles(overviewOnly=false){return [...state.battles].filter(b=>(battleFilter==='all'||battleFilter==='war'&&['Clan war','CWL'].includes(b.type)||b.type===battleFilter)&&(overviewOnly||!battleQuery||b.opponent.toLowerCase().includes(battleQuery.toLowerCase()))&&(overviewOnly||battlePeriod==='all'||Date.now()-new Date(b.date).getTime()<Number(battlePeriod)*86400000)).sort((a,b)=>new Date(b.date)-new Date(a.date));}
function battleTable(battles,full=false){return `<div class="table-scroll"><table class="battle-table ${full?'full-table':''}"><thead><tr><th>Opponent</th><th>Result</th><th>Loot earned</th><th class="hide-mid hide-small">Trophies</th><th class="hide-small">When</th><th><span class="visually-hidden">Details</span></th></tr></thead><tbody>${battles.map(b=>`<tr class="battle-row" data-battle="${esc(b.id)}" tabindex="0" aria-label="View ${esc(b.opponent)} battle details"><td><div class="opponent">${townHallArt(b.townHall)}<div><div class="opponent-name">${esc(b.opponent)}</div><div class="battle-type">${esc(b.type)}</div></div></div></td><td>${stars(b.stars)}<div class="destruction">${b.destruction}% destruction</div></td><td><div class="loot">${resourceArt('gold')}${compact(b.gold+b.elixir)}</div><div class="loot-small">${resourceArt('dark_elixir')}${compact(b.dark)} dark elixir</div></td><td class="hide-mid hide-small"><span class="trophy-change ${b.trophyChange<0?'negative':''}">${b.trophyChange>0?'+':''}${b.trophyChange} ${icon('trophy')}</span></td><td class="hide-small"><span class="battle-time">${relativeDate(b.date)}</span></td><td>${icon('chevron-right','row-chevron')}</td></tr>`).join('')||'<tr><td colspan="6" class="no-results">No battles here yet. Log a raid to get started.</td></tr>'}</tbody></table></div>`;}
function activityChart(){
  const days=chartPeriod;const today=new Date();today.setHours(0,0,0,0);
  const values=Array.from({length:days},(_,i)=>{const d=new Date(today);d.setDate(d.getDate()-(days-1-i));const match=state.snapshots.filter(s=>localDay(s.date)===localDay(d));const older=state.snapshots.filter(s=>new Date(s.date)<=new Date(d.getTime()+86400000));return {date:d,value:match.at(-1)?.trophies??older.at(-1)?.trophies??null};});
  const known=values.map(d=>d.value).filter(v=>v!==null);const min=known.length?Math.max(0,Math.floor((Math.min(...known)-40)/100)*100):0;const max=known.length?Math.ceil((Math.max(...known)+40)/100)*100:100;
  const pts=values.map((d,i)=>d.value===null?null:[i/(days-1)*900,112-(d.value-min)/(max-min)*100]).filter(Boolean);
  const line=pts.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const path=pts.length>1?`${line} L900,133 L${pts[0][0]},133Z`:'';
  const labelIndexes=days===7?[0,1,2,3,4,5,6]:[0,5,10,15,20,25,29];
  return `<section class="panel insights-panel"><div class="chart-heading"><div class="chart-title"><h2>The climb continues</h2><small>Trophy progress · ${'saved profile snapshots'}</small></div><div class="segmented" aria-label="Chart date range"><button class="${days===7?'active':''}" data-chart-days="7" aria-pressed="${days===7}">7 days</button><button class="${days===30?'active':''}" data-chart-days="30" aria-pressed="${days===30}">30 days</button></div></div><div class="chart-wrap"><div class="chart-axis"><span>${number(max)}</span><span>${number(Math.round((max+min)/2))}</span><span>${number(min)}</span></div><div class="chart-canvas"><div class="chart-grid"><span></span><span></span><span></span></div><svg class="activity-chart" viewBox="0 0 900 133" preserveAspectRatio="none" role="img" aria-label="Trophy history for the past ${days} days, ${known.length} days recorded"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#2563eb" stop-opacity=".19"/><stop offset="100%" stop-color="#2563eb" stop-opacity="0"/></linearGradient></defs>${path?`<path d="${path}" fill="url(#chart-fill)"/>`:''}<path d="${line}" fill="none" stroke="#3979e8" stroke-width="2.3" vector-effect="non-scaling-stroke" stroke-linejoin="round"/>${pts.length?`<circle cx="${pts.at(-1)[0]}" cy="${pts.at(-1)[1]}" r="4" fill="#2563eb" stroke="#ffffff" stroke-width="3" vector-effect="non-scaling-stroke"/>`:''}</svg><div class="chart-labels">${labelIndexes.map(i=>`<span>${values[i].date.toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span>`).join('')}</div></div></div></section>`;
}
function renderOverview(){const p=state.player;const today=todayBattles();const attacks=state.battles.filter(b=>b.type!=='Defense');const wins=attacks.filter(b=>b.stars>=1).length;const rate=attacks.length?(wins/attacks.length*100).toFixed(1):'0';const delta=state.snapshots.length>1?p.trophies-state.snapshots[Math.max(0,state.snapshots.length-7)].trophies:null;
return pageHeading('EVERY RAID. EVERY MILESTONE.',`Welcome back, ${esc(p.name)}.`,`Your village, in focus. Your next victory, in sight.`,`<span class="date-chip">${icon('calendar')}${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span><button class="button button-lime" data-action="log">${icon('plus')}Log a battle</button>`)+sourceNote()+`<section class="hero"><img class="hero-art" src="./assets/clash-official-banner.jpg" alt="Official Clash of Clans artwork featuring an Electro Dragon and attacking troops" fetchpriority="high"><div class="hero-content"><p class="eyebrow"><span>✦</span> A LITTLE MORE LEGENDARY</p><h2>Your village.<br><em>Every victory.</em></h2><p>From the first star to your biggest haul.<br>Keep your progress. Know your next move.</p><div class="hero-actions"><a class="button button-lime" href="#village">Explore my village ${icon('arrow-up-right')}</a><a class="button button-outline" href="#battles">View battle log ${icon('swords')}</a></div></div><div class="hero-caption">${icon('castle')}TOWN HALL ${number(p.townHallLevel)} · ${'YOUR VILLAGE'} <span class="hero-credit">· ART © SUPERCELL</span></div></section><div class="stats-grid">${statCard('Total trophies',number(p.trophies),'trophy','gold',delta!==null?`<span class="stat-trend">${icon('trending-up')}${delta>=0?'+':''}${number(delta)}</span><span>across snapshots</span>`:'<span>Import profiles to track changes</span>',null)}${statCard('Recorded attack wins',number(wins),'swords','',`<span class="stat-trend">${icon('arrow-up')}${today.filter(b=>b.stars>=1).length} today</span><span>in your battle log</span>`,null)}${statCard('Loot earned today',compact(totalLoot(today)),'coins','gold',`<span class="stat-trend">${today.length} raids</span><span>gold + elixir</span>`,null)}${statCard('Recorded win rate',`${rate}%`,'target','purple',`<span class="stat-trend">${attacks.length} attacks</span><span>one star or more</span>`,null)}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-header"><div class="section-topline" style="margin-bottom:0"><div class="section-heading"><h2>Recent battles</h2><span class="count">${state.battles.length}</span></div><a class="text-link" href="#battles">View all ${icon('arrow-up-right')}</a></div></div>${battleTabs()}${battleTable(filteredBattles(true).slice(0,4))}<div class="panel-foot"><span>${icon('info')} ${'Manually logged results · saved on this device'}</span><button class="subtle-link" data-action="log">Log a raid ${icon('plus')}</button></div></section>${activityChart()}</div><div class="right-stack">${playerPanel()}${lootPanel()}</div></div>`;
}
function renderBattles(){const filtered=filteredBattles(),perPage=8,pages=Math.max(1,Math.ceil(filtered.length/perPage));battlePage=Math.min(battlePage,pages-1);return pageHeading('THE STORY BEHIND THE STARS','Your battle journal.','Good raids deserve to be remembered.',`<button class="button button-lime" data-action="log">${icon('plus')}Log a battle</button>`)+sourceNote()+`<div class="toolbar">${battleTabs()}<div class="filter-group"><label class="search-field">${icon('search')}<input id="battle-search" aria-label="Search opponents" placeholder="Search opponent..." value="${esc(battleQuery)}"></label><label><span class="visually-hidden">Battle date range</span><select id="battle-period" class="filter-select"><option value="all" ${battlePeriod==='all'?'selected':''}>All time</option><option value="1" ${battlePeriod==='1'?'selected':''}>Last 24 hours</option><option value="7" ${battlePeriod==='7'?'selected':''}>Last 7 days</option><option value="30" ${battlePeriod==='30'?'selected':''}>Last 30 days</option></select></label></div></div><section class="panel">${battleTable(filtered.slice(battlePage*perPage,(battlePage+1)*perPage),true)}<div class="panel-foot"><span>${filtered.length} recorded battle${filtered.length===1?'':'s'} · ${'stored locally'}</span><div class="pagination"><button data-page="${battlePage-1}" ${battlePage===0?'disabled':''} aria-label="Previous battle page">${icon('chevron-left')}</button><span class="page-indicator">${battlePage+1} / ${pages}</span><button data-page="${battlePage+1}" ${battlePage>=pages-1?'disabled':''} aria-label="Next battle page">${icon('chevron-right')}</button></div></div></section>`;}
function troopPanel(title,items,type){return `<section class="panel panel-padding"><div class="section-topline" style="margin-bottom:0"><h2>${title}</h2><span class="count reduced-meta">${items?.length||0} recorded</span></div>${items?.length?`<div class="troops-grid">${items.map(t=>`<div class="troop-card" data-kind="${type}">${unitArt(t.name,type)}<h3>${esc(t.name)}</h3><p>Level <strong>${number(t.level)}</strong>${t.maxLevel?` / ${number(t.maxLevel)}`:''}</p>${t.maxLevel&&t.level>=t.maxLevel?'<span class="unit-maxed">MAX LEVEL</span>':''}</div>`).join('')}</div>`:'<p class="village-notice">Import your official player profile JSON to see your unlocked units and their levels here.</p>'}</section>`;}

function renderVillage(){const p=state.player;return pageHeading('HOME IS WHERE THE TOWN HALL IS','A village worth building.','Every level is a little closer to legendary.',`<button class="button button-lime" data-action="player">${icon('user-plus')}${'Edit player'}</button>`)+sourceNote()+`<div class="village-grid"><section class="panel village-profile"><div class="village-townhall">${townHallArt(p.townHallLevel)}<span class="village-level">PLAYER LEVEL ${number(p.expLevel)}</span></div><h2>${esc(p.name)}</h2><p>${esc(p.tag)} · ${esc(p.clan?.name||'No clan')}</p><div class="profile-meta"><div><small>Town Hall</small><strong>Level ${p.townHallLevel}</strong></div><div><small>Trophies</small><strong>${icon('trophy')}${number(p.trophies)}</strong></div><div><small>Best trophies</small><strong>${number(p.bestTrophies||p.trophies)}</strong></div><div><small>War stars</small><strong>${number(p.warStars)}</strong></div><div><small>Donations</small><strong>${number(p.donations)}</strong></div><div><small>Received</small><strong>${number(p.donationsReceived)}</strong></div></div><button class="button button-outline" data-action="import-profile">${icon('upload')}Import player profile</button><p class="village-notice">${'Profile updated '+new Date(state.updatedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})+'. Import a fresh profile to record changes to your trophies and unit levels.'}</p></section><div class="village-panels">${troopPanel('Your heroes',p.heroes,'heroes')}${troopPanel('Troops & siege machines',p.troops,'troops')}${troopPanel('A little spell power',p.spells,'spells')}${activityChart()}</div></div>`;}
function renderLeaderboard(){const all=leaderboardData(),top=all.slice(0,3);return pageHeading('FORTUNE FAVORS THE RAID','The biggest hauls.','Your best attacks, ranked by gold + elixir collected.',`<button class="button button-lime" data-action="log">${icon('plus')}Log a raid</button>`)+sourceNote()+`<div class="toolbar"><div class="segmented" aria-label="Loot leaderboard date range">${[['today','Today'],['week','This week'],['all','All time']].map(([v,l])=>`<button data-leader-period="${v}" class="${leaderPeriod===v?'active':''}" aria-pressed="${leaderPeriod===v}">${l}</button>`).join('')}</div><span class="reduced-meta">${all.length} raids · ${esc(state.player.name)}</span></div><div class="summary-grid"><div class="panel summary-card"><span class="stat-icon gold">${icon('coins')}</span><div><small>Total gold & elixir</small><strong>${compact(totalLoot(all))}</strong></div></div><div class="panel summary-card"><span class="stat-icon purple">${icon('droplet')}</span><div><small>Reported dark elixir</small><strong>${all.length&&!all.some(b=>Number.isFinite(b.dark))?'—':compact(all.reduce((n,b)=>n+(Number.isFinite(b.dark)?b.dark:0),0))}</strong></div></div><div class="panel summary-card"><span class="stat-icon">${icon('target')}</span><div><small>Average haul per raid</small><strong>${compact(all.length?Math.round(totalLoot(all)/all.length):0)}</strong></div></div></div>${top.length?`<div class="podium-grid">${top.map((b,i)=>`<button class="podium-card" data-battle="${esc(b.id)}"><span class="rank-medal">0${i+1}</span><span class="leader-avatar ${i===0?'gold':i===2?'purple':''}">${esc(b.opponent.slice(0,1))}</span><h3>${esc(b.opponent)}</h3><p>${Number.isFinite(b.townHall)?'TH '+b.townHall+' · ':''}${Number.isFinite(b.stars)?b.stars+' stars':'Stars unavailable'}${Number.isFinite(b.destruction)?' · '+b.destruction+'%':''}</p><div class="podium-value">${compact(b.gold+b.elixir)}</div><div class="loot-breakdown"><span>${resourceArt('gold')}${compact(b.gold)}</span><span>${resourceArt('elixir')}${compact(b.elixir)}</span></div></button>`).join('')}</div>`:'<section class="panel"><div class="empty-state"><span class="empty-icon">'+icon('trophy')+'</span><h2>A new day. A new high score.</h2><p>Log your first raid for this period and give the top spot a name.</p><button class="button button-lime" data-action="log">'+icon('plus')+'Log a raid</button></div></section>'}${all.length?`<section class="panel"><div class="loot-heading">All recorded raids · sorted by loot earned</div>${battleTable(all,true)}</section>`:''}<p class="village-notice">This leaderboard compares ${'your recorded attacks'}. It is not a global ranking. Dark elixir is listed separately.</p>`;}
function renderReplays(){return pageHeading('THE ONES WORTH WATCHING AGAIN','Keep the good attacks.','Your own recordings. Your own highlight reel.',`<button class="button button-lime" data-action="replay">${icon('plus')}Add a replay</button>`)+`<div class="callout-inline">${icon('info')}<span>Watch your uploaded videos or saved YouTube links. In-game replays aren’t imported automatically.</span><button data-action="about">How it works ${icon('arrow-up-right')}</button></div><div class="replay-grid">${state.replays.map(r=>`<article class="replay-card"><button class="replay-cover" style="width:100%" data-play="${esc(r.id)}" aria-label="Play ${esc(r.title)}">${r.youtube?`<img src="https://i.ytimg.com/vi/${esc(r.youtube)}/hqdefault.jpg" alt="${esc(r.title)} video thumbnail" loading="lazy">`:`<img src="./assets/clash-official-banner.jpg" alt="Official Clash of Clans promotional artwork used as a recording cover" loading="lazy">`}<span class="play-circle">${icon('play')}</span><span class="video-label">${r.youtube?'YOUTUBE':'LOCAL RECORDING'}</span></button><div class="replay-info"><h3>${esc(r.title)}</h3><p>${new Date(r.date).toLocaleDateString('en-US',{month:'short',day:'numeric'})} · ${r.youtube?'Saved video link':'Stored on this device'}</p><div class="replay-card-bottom"><button class="text-link" data-play="${esc(r.id)}">Watch replay ${icon('arrow-up-right')}</button><button class="icon-button" data-delete-replay="${esc(r.id)}" aria-label="Remove ${esc(r.title)}">${icon('trash')}</button></div></div></article>`).join('')}<button class="replay-add-card" data-action="replay"><span><span class="empty-icon">${icon('upload')}</span><h3>${state.replays.length?'One more for the collection?':'Your highlight reel starts here.'}</h3><p>Upload an attack recording<br>or save a YouTube video.</p></span></button></div>${!state.replays.length?'<p class="village-notice">Add your first recording and it will be ready to watch, right in your library.</p>':''}`;}

function updateSidebar(){const p=state.player;$('#sidebar-player-name').textContent=p.name;$('#sidebar-source').textContent=hasPlayer()?'Saved on this device':'No player connected';$('#battle-count').textContent=state.battles.length;$('#top-profile').textContent=hasPlayer()?p.name.slice(0,1).toUpperCase():'+';$('.sidebar-profile .avatar').textContent=hasPlayer()?p.name.slice(0,1).toUpperCase():'+';$('#breadcrumb-title').textContent=VIEWS[view];$$('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function render(){const renders={overview:renderOverview,battles:renderBattles,village:renderVillage,leaderboard:renderLeaderboard,replays:renderReplays};$('#main-content').innerHTML=!hasPlayer()&&view!=='replays'?renderDisconnected():(renders[view]||renderOverview)();updateSidebar();document.title=`${VIEWS[view]} · MARINE X DURUGISTA`;}
function navigate(next){if(!VIEWS[next])next='overview';if(location.hash!==`#${next}`)location.hash=next;else{view=next;render();}closeNavigation();}
function syncNavigationAccessibility(){$('#sidebar').inert=matchMedia('(max-width:520px)').matches&&!$('#sidebar').classList.contains('open');}
function closeNavigation(){$('#sidebar').classList.remove('open');$('#nav-scrim').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');syncNavigationAccessibility();}
function modal(content,cls=''){closeModal();const d=$('#modal');d.className=`modal ${cls}`;$('#modal-content').innerHTML=content;d.showModal();}
function closeModal(){const d=$('#modal');if(d.open)d.close();if(modalCleanup){modalCleanup();modalCleanup=null;}objectUrls.forEach(u=>URL.revokeObjectURL(u));objectUrls=[];}
function modalHeader(title,description=''){return `<div class="modal-header"><div><h2 id="modal-title">${title}</h2>${description?`<p>${description}</p>`:''}</div><button class="icon-button" data-close aria-label="Close dialog">${icon('x')}</button></div>`;}
function field(label,name,options={}){const{type='text',value='',placeholder='',min,max,required=false,step}=options;return `<div class="form-field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${placeholder?`placeholder="${esc(placeholder)}"`:''} ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} ${step?`step="${step}"`:''} ${required?'required':''} ${type==='text'?'maxlength="80"':''}></div>`;}
function openPlayer(){modal('<div class="modal-content">'+modalHeader('Connect your village','Player lookup is loading. Refresh this page if it does not appear.')+'<button class="button button-lime" data-close>Done</button></div>');}
function normalizedTag(value){return String(value).trim().toUpperCase().replace(/^#/,'');}
function validTag(value){return /^[0289PYLQGRJCUV]{3,15}$/.test(normalizedTag(value));}
function savePlayer(event){event.preventDefault();const f=new FormData(event.target);const tag='#'+normalizedTag(f.get('player-tag'));if(!validTag(tag)){$('#player-error').textContent='Enter a valid CoC player tag, using the tag shown below your name in-game.';return;}if(hasPlayer()&&tag!==state.player.tag){openReplacePlayer({tag,name:String(f.get('player-name')).trim(),townHallLevel:Number(f.get('player-th')),expLevel:Number(f.get('player-level')),trophies:Number(f.get('player-trophies')),clan:{name:String(f.get('player-clan')).trim()}});return;}const fresh=!hasPlayer();const player={...(fresh?{}:state.player),tag,name:String(f.get('player-name')).trim(),townHallLevel:Number(f.get('player-th')),expLevel:Number(f.get('player-level')),trophies:Number(f.get('player-trophies')),clan:{name:String(f.get('player-clan')).trim()}};activatePlayer(player,'manual',fresh);}
function openReplacePlayer(player,source='manual'){modal(`<div class="modal-content">${modalHeader('Start a different village?',`You’re switching from ${esc(state.player.name)} to ${esc(player.name)}. Each village starts with a separate, empty journal.`)}<p class="source-explanation">Export your current records before switching to keep a backup. Saved video files remain on this device, but they aren’t included in exports.</p><div class="form-actions"><button class="button button-outline" data-action="export">${icon('download')}Export current records</button><button class="button button-lime" id="confirm-replace">Start new village</button></div></div>`);$('#confirm-replace').addEventListener('click',()=>activatePlayer(player,source,true));}
function activatePlayer(player,source,fresh=false){const previous=state;const p={...player,bestTrophies:Math.max(Number(player.bestTrophies||0),Number(player.trophies||0))};state={...state,demo:false,source,player:p,updatedAt:new Date().toISOString(),...(fresh?{battles:[],snapshots:[],replays:hasPlayer()?[]:state.replays}:{}),snapshots:[...(fresh?[]:state.snapshots),{date:new Date().toISOString(),trophies:Number(p.trophies||0)}]};if(!saveState()){state=previous;return;}closeModal();battleFilter='all';battleQuery='';battlePage=0;render();toast('Your village is saved. Let the next chapter begin.');}
async function lookupPlayer(){const btn=$('#lookup-player'),tag=$('#player-tag').value;if(!validTag(tag)){$('#player-error').textContent='Enter a valid player tag first.';return;}btn.disabled=true;btn.textContent='Looking up player...';try{const response=await fetch(`/api/players/${encodeURIComponent('#'+normalizedTag(tag))}`,{signal:AbortSignal.timeout(15000)});const profile=await response.json();if(!response.ok)throw new Error(profile.error||'Player lookup failed.');if(hasPlayer()&&profile.tag!==state.player.tag)openReplacePlayer(profile,'api');else activatePlayer(profile,'api',!hasPlayer());}catch(e){$('#player-error').textContent=e.name==='TimeoutError'?'The request timed out. Try again.':e.message;btn.disabled=false;btn.innerHTML=icon('search')+'Look up official profile';}}
function openLog(){if(!hasPlayer()){openPlayer();return;}
 const now=new Date();now.setMinutes(now.getMinutes()-now.getTimezoneOffset());modal(`<div class="modal-content">${modalHeader('Every raid has a story.','Save the result from your in-game attack log. Gold and elixir power your loot leaderboard.')}<form id="battle-form">${field('Opponent name','opponent',{placeholder:'The village you raided',required:true})}<div class="form-grid"><div class="form-field"><label for="battle-type">Battle type</label><select id="battle-type" name="type">${TYPES.map(t=>`<option>${t}</option>`).join('')}</select></div>${field('Opponent Town Hall','townHall',{type:'number',value:state.player.townHallLevel,min:1,max:100,required:true})}<div class="form-field"><label for="battle-stars">Stars earned</label><select id="battle-stars" name="stars"><option value="3">★★★ · 3 stars</option><option value="2">★★ · 2 stars</option><option value="1">★ · 1 star</option><option value="0">0 stars</option></select></div>${field('Destruction (%)','destruction',{type:'number',value:100,min:0,max:100,required:true})}${field('Gold collected','gold',{type:'number',value:0,min:0,max:100000000,required:true})}${field('Elixir collected','elixir',{type:'number',value:0,min:0,max:100000000,required:true})}${field('Dark elixir','dark',{type:'number',value:0,min:0,max:10000000,required:true})}${field('Trophy change','trophyChange',{type:'number',value:0,min:-1000,max:1000,required:true})}</div><div style="margin-top:15px">${field('When was the attack?','battle-date',{type:'datetime-local',value:now.toISOString().slice(0,16),required:true})}</div><div class="form-field"><label for="battle-notes">Notes (optional)</label><textarea id="battle-notes" name="notes" maxlength="1000" placeholder="Army, strategy, or the moment that made the raid..."></textarea></div><p class="form-error" id="battle-error" role="alert"></p><div class="form-actions"><button type="button" class="button button-ghost" data-close>Cancel</button><button type="submit" class="button button-lime">Save this raid ${icon('check')}</button></div></form></div>`);$('#battle-form').addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.target);const destruction=Number(f.get('destruction')),starCount=Number(f.get('stars'));const date=new Date(f.get('battle-date'));if(date.getTime()>Date.now()+60000){$('#battle-error').textContent='Choose an attack time in the past.';return;}if(starCount===3&&destruction!==100||destruction===100&&starCount!==3||starCount===0&&destruction>=50){$('#battle-error').textContent='Check the result: 100% earns 3 stars, and at least 50% earns 1 or more.';return;}const b={id:uid(),opponent:String(f.get('opponent')).trim(),type:String(f.get('type')),townHall:Number(f.get('townHall')),stars:starCount,destruction,gold:Number(f.get('gold')),elixir:Number(f.get('elixir')),dark:Number(f.get('dark')),trophyChange:Number(f.get('trophyChange')),date:date.toISOString(),notes:String(f.get('notes')).trim(),demo:false};state.battles.unshift(b);if(!saveState()){state.battles.shift();return;}closeModal();render();toast('Another raid in the books. Nicely done.');});}
function openBattle(id){const b=state.battles.find(b=>b.id===id);if(!b)return;modal(`<div class="modal-content">${modalHeader(`<span class="detail-title-tag">${townHallArt(b.townHall)}${esc(b.opponent)}</span>`,`${esc(b.type)} · ${new Date(b.date).toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short'})}${''}`)}<div class="detail-score">${stars(b.stars)}<strong>${b.destruction}%</strong><small>${b.stars===3?'A perfect three-star finish.':b.stars>=1?'Another victory in the journal.':'A raid to learn from.'}</small></div><div class="detail-data"><div>${resourceArt('gold')}<small>Gold</small><strong>${number(b.gold)}</strong></div><div>${resourceArt('elixir')}<small>Elixir</small><strong>${number(b.elixir)}</strong></div><div>${resourceArt('dark_elixir')}<small>Dark elixir</small><strong>${number(b.dark)}</strong></div></div><p class="detail-note">${b.notes?esc(b.notes):'No strategy notes saved for this attack.'}</p><div class="form-info">${icon('play-square')}<span>Want to watch this attack? Add your own screen recording or YouTube video to the replay library.</span></div><div class="form-actions">${true?`<button class="danger-link" data-remove-battle="${esc(b.id)}">Delete record</button>`:''}<button class="button button-outline" data-action="replay">${icon('play')}Add a recording</button><button class="button button-lime" data-close>Done</button></div></div>`);}

const videoDB = new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('Video storage is unavailable in this browser.'));return;}const req=indexedDB.open('raidroom-videos',1);req.onupgradeneeded=()=>req.result.createObjectStore('videos');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
videoDB.catch(()=>{});
async function videoStore(op,id,value){const db=await videoDB;return new Promise((resolve,reject)=>{const tx=db.transaction('videos',op==='get'?'readonly':'readwrite');const store=tx.objectStore('videos');const req=op==='put'?store.put(value,id):op==='delete'?store.delete(id):store.get(id);let result;req.onsuccess=()=>{result=req.result;};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Video storage was interrupted.'));});}
function parseYoutube(value){try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))return null;let id;if(['youtube.com','www.youtube.com','m.youtube.com','youtube-nocookie.com','www.youtube-nocookie.com'].includes(u.hostname)){id=u.searchParams.get('v')||u.pathname.match(/^\/(?:shorts|embed)\/([\w-]+)/)?.[1];}else if(u.hostname==='youtu.be')id=u.pathname.slice(1).split('/')[0];return /^[A-Za-z0-9_-]{11}$/.test(id||'')?id:null;}catch{return null;}}
function openReplay(){modal(`<div class="modal-content">${modalHeader('Save a little greatness.','Add an attack recording to watch here whenever you need a little inspiration.')}<form id="replay-form">${field('Recording title','replay-title',{placeholder:'Queen charge · The perfect finish',required:true})}${field('YouTube video link','replay-url',{type:'url',placeholder:'https://www.youtube.com/watch?v=...'})}<div class="form-field"><label for="replay-file">Or upload a screen recording</label><input id="replay-file" type="file" accept="video/mp4,video/webm,video/quicktime,video/ogg"><small>MP4 recommended · up to 100 MB. Uploads stay on this device and are not included in JSON backups.</small></div><div class="form-info">${icon('shield')}<span>These are your own videos. The official game’s playable replays are not fetched through this site.</span></div><p class="form-error" id="replay-error" role="alert"></p><div class="form-actions"><button type="button" class="button button-ghost" data-close>Cancel</button><button type="submit" class="button button-lime">Add to my library ${icon('plus')}</button></div></form></div>`);$('#replay-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,title=$('#replay-title').value.trim(),url=$('#replay-url').value.trim(),file=$('#replay-file').files[0];const error=$('#replay-error');if(!url&&!file){error.textContent='Add a YouTube link or choose a video file.';return;}if(url&&file){error.textContent='Choose one source: a YouTube link or a video file.';return;}const youtube=url?parseYoutube(url):null;if(url&&!youtube){error.textContent='Enter a valid YouTube video link.';return;}if(file&&(!file.type.startsWith('video/')||file.size>100*1024*1024)){error.textContent='Choose a video file smaller than 100 MB.';return;}const btn=$('button[type=submit]',form);btn.disabled=true;btn.textContent='Saving your recording...';const id=uid();try{if(file)await videoStore('put',id,file);state.replays.unshift({id,title,youtube,date:new Date().toISOString(),local:!!file});if(!saveState()){state.replays.shift();if(file)await videoStore('delete',id);btn.disabled=false;btn.textContent='Try saving again';return;}closeModal();navigate('replays');toast('Saved to your highlight reel.');}catch{error.textContent='This browser could not store the video. Try a smaller MP4 or save a YouTube link.';btn.disabled=false;btn.textContent='Add to my library';}});}
async function playReplay(id){const r=state.replays.find(r=>r.id===id);if(!r)return;let url;if(!r.youtube){try{const blob=await videoStore('get',r.id);if(!blob){toast('This video is missing from this device. Please add the recording again.');return;}url=URL.createObjectURL(blob);}catch{toast('Video storage is unavailable. Try a YouTube link.');return;}}modal(`${r.youtube?`<iframe class="video-player" src="https://www.youtube-nocookie.com/embed/${r.youtube}?autoplay=1&rel=0" title="${esc(r.title)}" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`:`<video class="video-player" src="${url}" controls autoplay playsinline></video>`}<div class="video-footer"><div><h2 id="modal-title">${esc(r.title)}</h2><p>${r.youtube?'Saved YouTube recording':'Your screen recording · stored on this device'}</p></div><button class="icon-button" data-close aria-label="Close video">${icon('x')}</button></div>`,'video-dialog');if(url)objectUrls.push(url);modalCleanup=()=>{$('video',$('#modal'))?.pause();$('#modal-content').innerHTML='';};}
function confirmDeleteReplay(id){const r=state.replays.find(r=>r.id===id);if(!r)return;modal(`<div class="modal-content">${modalHeader('Remove this recording?',`${esc(r.title)} will be removed from your MARINE X DURUGISTA library.${r.local?' The locally stored video copy will also be deleted.':''}`)}<div class="form-actions"><button class="button button-ghost" data-close>Keep recording</button><button class="button button-outline" id="confirm-delete-video">Remove recording</button></div></div>`);$('#confirm-delete-video').addEventListener('click',async()=>{const previous=state.replays;state.replays=state.replays.filter(v=>v.id!==id);if(!saveState()){state.replays=previous;return;}try{if(r.local)await videoStore('delete',id);}catch{}closeModal();render();toast('Recording removed from your library.');});}
function openAbout(){modal(`<div class="modal-content">${modalHeader('Know your village. Own your progress.','MARINE X DURUGISTA is an independent companion for the raids, upgrades, and little victories that make your village yours.')}<div class="source-explanation"><p><strong>Player profiles.</strong> Enter a player tag to detect public profile details automatically. The secure server loads your name, level, Town Hall, troops, spells, and heroes. Profile updates save trophy snapshots.</p><p><strong>Battle journal & loot.</strong> Recent results come from the game API, with collected history and rankings from ClashKing. Coverage varies by player and provider; missing values stay unknown. You can also log attacks manually. Loot rankings use reported gold and elixir in your own journal. No sample player or battle records are included.</p><p><strong>Clan hub.</strong> View a live roster, inspect members, compare recorded loot and attacks by calendar day, week, or month, and follow the current war. Clan activity observations are saved in the local server database. Coverage depends on available history; open the dashboard to collect updates.</p><p><strong>Recordings.</strong> Watch uploaded screen recordings and saved YouTube videos. MARINE X DURUGISTA does not automatically fetch playable in-game replays.</p><p><strong>Your records.</strong> Personal journals are saved in this browser; clan activity is retained by the local server. Export a JSON backup before clearing browser data or changing devices. Video files stay in this browser and need to be kept separately.</p><p>This material is unofficial and is not endorsed by Supercell. See <a href="https://supercell.com/en/fan-content-policy/" target="_blank" rel="noopener noreferrer">Supercell’s Fan Content Policy</a>.</p></div><div class="form-actions"><button class="button button-outline" data-action="export">${icon('download')}Export my records</button><button class="button button-lime" data-close>Back to the village</button></div></div>`);}
function exportRecords(){const backup={...state,exportedAt:new Date().toISOString(),replays:state.replays.filter(r=>r.youtube),backupNote:'Local video files are not included. Save your original recordings separately.'};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`raidroom-${localDay(new Date())}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Records exported. Local video files aren’t included.');}
function cleanUnits(units){return Array.isArray(units)?units.slice(0,300).filter(u=>typeof u.name==='string'&&Number.isFinite(u.level)).map(u=>({name:u.name.slice(0,80),level:Math.max(0,Math.min(1000,u.level)),maxLevel:Math.max(u.level,Math.min(1000,Number(u.maxLevel)||u.level)),village:u.village==='builderBase'?'builderBase':'home',category:typeof u.category==='string'?u.category:null,townHallMaxLevel:Number.isFinite(u.townHallMaxLevel)?u.townHallMaxLevel:null})):[];}
function cleanPlayer(p){if(!p||typeof p.name!=='string'||!p.name.trim()||!validTag(p.tag)||!Number.isInteger(p.townHallLevel)||p.townHallLevel<1||p.townHallLevel>100)throw new Error('Choose an official player-profile JSON with name, tag, and townHallLevel.');const n=(key,max=1000000)=>Math.max(0,Math.min(max,Number(p[key])||0));return{name:p.name.slice(0,80),tag:'#'+normalizedTag(p.tag),townHallLevel:p.townHallLevel,expLevel:n('expLevel',1000)||1,trophies:n('trophies'),bestTrophies:n('bestTrophies'),warStars:n('warStars'),attackWins:n('attackWins'),donations:n('donations'),donationsReceived:n('donationsReceived'),clan:{name:String(p.clan?.name||'').slice(0,80)},league:{name:String(p.league?.name||'Unranked').slice(0,80)},heroes:cleanUnits(p.heroes),troops:cleanUnits(p.troops),spells:cleanUnits(p.spells)};}
async function importProfile(file){if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Choose a profile JSON smaller than 2 MB.');const parsed=JSON.parse(await file.text());const p=cleanPlayer(parsed.player||parsed);if(hasPlayer()&&p.tag!==state.player.tag)openReplacePlayer(p,'import');else activatePlayer(p,'import',!hasPlayer());}catch(e){toast(e.message||'That profile could not be imported.');}}
function readBackup(parsed){if(parsed.version!==1||!Array.isArray(parsed.battles)||!Array.isArray(parsed.snapshots))throw new Error('Choose a MARINE X DURUGISTA JSON backup.');if(parsed.demo||parsed.source==='demo')throw new Error('Sample backups are no longer supported. Connect a real player instead.');const player=cleanPlayer(parsed.player);const numeric=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max;const battles=parsed.battles.filter(b=>!RaidroomRecords.isSampleBattle(b)).slice(0,10000).map(b=>{if(!b||typeof b.opponent!=='string'||!TYPES.includes(b.type)||!numeric(b.stars,0,3)||!numeric(b.destruction,0,100)||!numeric(b.gold,0,1e8)||!numeric(b.elixir,0,1e8)||!numeric(b.dark,0,1e7)||!numeric(b.trophyChange,-1000,1000)||!numeric(b.townHall,1,100)||!Number.isFinite(new Date(b.date).getTime()))throw new Error('This backup contains an invalid battle record.');return{id:uid(),opponent:b.opponent.slice(0,80),type:b.type,townHall:b.townHall,stars:b.stars,destruction:b.destruction,gold:b.gold,elixir:b.elixir,dark:b.dark,trophyChange:b.trophyChange,date:new Date(b.date).toISOString(),notes:String(b.notes||'').slice(0,1000),demo:false};});const snapshots=parsed.snapshots.slice(0,10000).filter(s=>Number.isFinite(new Date(s.date).getTime())&&numeric(s.trophies,0,1e6)).map(s=>({date:new Date(s.date).toISOString(),trophies:s.trophies}));const replays=Array.isArray(parsed.replays)?parsed.replays.filter(r=>r&&typeof r.title==='string'&&/^[A-Za-z0-9_-]{11}$/.test(r.youtube||'')).slice(0,500).map(r=>({id:uid(),title:r.title.slice(0,80),youtube:r.youtube,local:false,date:Number.isFinite(new Date(r.date).getTime())?new Date(r.date).toISOString():new Date().toISOString()})):[];return{version:1,demo:false,source:'import',player,battles,snapshots,replays,updatedAt:new Date().toISOString()};}
async function restoreBackup(file){if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Choose a backup smaller than 10 MB.');const restored=readBackup(JSON.parse(await file.text()));modal(`<div class="modal-content">${modalHeader('Bring your journal back.',`This backup contains ${restored.battles.length} battles and ${restored.replays.length} YouTube recordings for ${esc(restored.player.name)}.`)}<p class="source-explanation">Restoring replaces your current journal. Export your current records first if you want to keep them. Local video files aren’t restored from JSON.</p><div class="form-actions"><button class="button button-outline" data-action="export">Export current</button><button class="button button-lime" id="confirm-restore">Restore backup</button></div></div>`);$('#confirm-restore').addEventListener('click',()=>{const old=state;state=restored;if(!saveState()){state=old;return;}closeModal();battlePage=0;battleFilter='all';battleQuery='';render();toast('Your journal is back. Welcome home.');});}catch(e){toast(e.message||'This backup could not be restored.');}}
const actions={player:openPlayer,log:openLog,replay:openReplay,about:openAbout,export:exportRecords,'import-profile':()=>$('#profile-import').click(),restore:()=>$('#backup-import').click(),'copy-tag':async()=>{try{await navigator.clipboard.writeText(state.player.tag);toast('Player tag copied.');}catch{toast(`Player tag: ${state.player.tag}`);}}};
document.addEventListener('click',event=>{const close=event.target.closest('[data-close]');if(close){closeModal();return;}const action=event.target.closest('[data-action]');if(action){actions[action.dataset.action]?.();return;}const battle=event.target.closest('[data-battle]');if(battle){openBattle(battle.dataset.battle);return;}const filter=event.target.closest('[data-filter]');if(filter){battleFilter=filter.dataset.filter;battlePage=0;render();const next=$(`[data-filter="${battleFilter}"]`);next?.focus({preventScroll:true});return;}const days=event.target.closest('[data-chart-days]');if(days){chartPeriod=Number(days.dataset.chartDays);render();return;}const period=event.target.closest('[data-leader-period]');if(period){leaderPeriod=period.dataset.leaderPeriod;render();return;}const page=event.target.closest('[data-page]');if(page){battlePage=Number(page.dataset.page);render();return;}const play=event.target.closest('[data-play]');if(play){playReplay(play.dataset.play);return;}const delReplay=event.target.closest('[data-delete-replay]');if(delReplay){confirmDeleteReplay(delReplay.dataset.deleteReplay);return;}const delBattle=event.target.closest('[data-remove-battle]');if(delBattle){const b=state.battles.find(b=>b.id===delBattle.dataset.removeBattle);if(b){modal(`<div class="modal-content">${modalHeader('Remove this battle?',`${esc(b.opponent)} will be removed from your battle journal and loot rankings.`)}<div class="form-actions"><button class="button button-ghost" data-close>Keep battle</button><button class="button button-outline" id="confirm-delete-battle">Remove battle</button></div></div>`);$('#confirm-delete-battle').addEventListener('click',()=>{const previous=state.battles;state.battles=state.battles.filter(item=>item.id!==b.id);if(!saveState()){state.battles=previous;return;}closeModal();render();toast('Battle removed from your journal.');});}}});
document.addEventListener('keydown',event=>{const row=event.target.closest('[data-battle]');if(row&&(event.key==='Enter'||event.key===' ')){event.preventDefault();openBattle(row.dataset.battle);}if(event.key==='/'&&!$('#modal').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();openPlayer();}if(event.key==='Escape')closeNavigation();});
document.addEventListener('input',event=>{if(event.target.id==='battle-search'){const start=event.target.selectionStart;battleQuery=event.target.value;battlePage=0;render();const input=$('#battle-search');input.focus();input.setSelectionRange(start,start);}});
document.addEventListener('change',event=>{if(event.target.id==='battle-period'){battlePeriod=event.target.value;battlePage=0;render();}});
window.addEventListener('hashchange',()=>{view=VIEWS[location.hash.slice(1)]?location.hash.slice(1):'overview';render();window.scrollTo({top:0,behavior:'instant'});closeNavigation();});
$('#profile-import').addEventListener('change',event=>{importProfile(event.target.files[0]);event.target.value='';});
$('#backup-import').addEventListener('change',event=>{restoreBackup(event.target.files[0]);event.target.value='';});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const rect=event.target.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();}});
$('#modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
$('#mobile-menu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#nav-scrim').classList.toggle('open',open);$('#mobile-menu').setAttribute('aria-expanded',String(open));syncNavigationAccessibility();});
$('#nav-scrim').addEventListener('click',closeNavigation);
for(const id of ['add-player-side','start-tracking','profile-button','top-profile','player-search'])$('#'+id).addEventListener('click',()=>{closeNavigation();openPlayer();});
$('#export-side').addEventListener('click',exportRecords);$('#help-button').addEventListener('click',openAbout);
document.addEventListener('error',event=>{const image=event.target;if(image instanceof HTMLImageElement&&image.hasAttribute('data-game-art')){image.hidden=true;image.closest('.game-art')?.classList.add('asset-fallback');}},true);
hydrateIcons();render();syncNavigationAccessibility();matchMedia('(max-width:520px)').addEventListener('change',closeNavigation);
if(['localhost','127.0.0.1','[::1]'].includes(location.hostname))fetch('/api/status').then(r=>r.ok?r.json():{}).then(data=>{apiConnected=!!data.connected;}).catch(()=>{});
